<script setup>
import RedesignTopbar from './RedesignTopbar.vue';
import { Head, Link, router, useForm, usePage } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
import AdminSidebar from './AdminSidebar.vue';

const props = defineProps({ event: { type: Object, required: true }, availableGuides: { type: Array, default: () => [] }, availableQuests: { type: Array, default: () => [] }, participantCount: Number, timezone: { type: String, default: 'UTC' } });
const page = usePage();
const guideForm = useForm({ guide_ids: [] });
const questForm = useForm({ quest_ids: [] });
const showGuidePicker = ref(false);
const showQuestPicker = ref(false);
const removing = ref(null);
const images = computed(() => [...(props.event.images || [])].sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0)));
const guides = computed(() => [...(props.event.guides || [])].sort((a, b) => (a.pivot?.sort_order || 0) - (b.pivot?.sort_order || 0)));
const quests = computed(() => [...(props.event.quests || [])].sort((a, b) => (a.pivot?.sort_order || 0) - (b.pivot?.sort_order || 0)));
const availableUnlinkedGuides = computed(() => props.availableGuides.filter(item => !guides.value.some(linked => linked.id === item.id)));
const availableUnlinkedQuests = computed(() => props.availableQuests.filter(item => !quests.value.some(linked => linked.id === item.id)));
const backUrl = computed(() => props.event.study_group?.uuid ? route('redesign.study-groups.events', props.event.study_group.uuid) : route('redesign.events'));
const date = value => value ? new Intl.DateTimeFormat('id-ID', { timeZone: props.timezone, day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }).format(new Date(value)) : 'Belum dijadwalkan';
const shortDate = value => value ? new Intl.DateTimeFormat('id-ID', { timeZone: props.timezone, day: '2-digit', month: 'short' }).format(new Date(value)) : '—';
const imageUrl = path => `/storage/${String(path || '').replace(/^\/+/, '')}`;
const attachGuides = () => guideForm.post(route('admin.events.guides.attach', props.event.uuid), { preserveScroll: true, preserveState: false, onSuccess: () => { guideForm.reset(); showGuidePicker.value = false; } });
const attachQuests = () => questForm.post(route('admin.events.quests.attach', props.event.uuid), { preserveScroll: true, preserveState: false, onSuccess: () => { questForm.reset(); showQuestPicker.value = false; } });
const detach = () => {
    if (!removing.value) return;
    const { type, item } = removing.value;
    router.delete(type === 'guide' ? route('admin.events.guides.detach', { event: props.event.uuid, guide: item.uuid }) : route('admin.events.quests.detach', { event: props.event.uuid, quest: item.uuid }), { preserveScroll: true, preserveState: false, onSuccess: () => { removing.value = null; } });
};
</script>

<template>
    <Head :title="event.title" />
    <div class="event-detail-app"><AdminSidebar /><main>
        <RedesignTopbar breadcrumb="Materi &amp; event" />
        <div class="content"><div class="heading"><Link :href="backUrl" class="back">← Event kelas</Link><div><h1>{{ event.title }}</h1><div class="heading-actions"><Link class="preview" :href="route('events.user-preview', { event: event.uuid, from: 'redesign' })">User View</Link><Link class="edit" :href="route('redesign.events.edit', event.uuid)">Edit event</Link></div></div><p>{{ event.study_group?.name || (event.job?.name ? `Event umum · ${event.job.name}` : 'Event umum') }}</p></div>
            <section class="metrics" aria-label="Ringkasan event"><div class="metric"><span>Kelas</span><strong>{{ event.study_group?.name || 'Umum' }}</strong><i></i></div><div class="metric"><span>Jadwal</span><strong>{{ shortDate(event.starts_at) }}</strong><i></i></div><div class="metric"><span>Peserta</span><strong>{{ participantCount ?? '—' }}</strong><i></i></div><div class="metric"><span>Self attend</span><strong>{{ event.self_attendance_enabled ? 'Aktif' : 'Nonaktif' }}</strong><i></i></div></section>
            <div class="columns"><section class="panel main-panel"><h2>{{ event.title }}</h2><p class="schedule">{{ date(event.starts_at) }} <span v-if="event.ends_at">– {{ date(event.ends_at) }}</span></p><div v-if="images.length" class="image-grid"><img v-for="image in images" :key="image.id" :src="imageUrl(image.path)" :alt="`Gambar ${event.title}`" /></div><div v-else class="visual-placeholder"><strong>{{ event.title }}</strong><span>{{ event.study_group?.name || 'Event pembelajaran' }}</span></div><p class="description">{{ event.description || 'Belum ada deskripsi untuk event ini.' }}</p><Link class="primary" :href="route('redesign.events.attendance', event.uuid)">Buka absensi</Link></section>
                <aside><section class="panel attachment"><h2>Materi terlampir</h2><ol v-if="guides.length"><li v-for="(guide,index) in guides" :key="guide.id"><span class="order">{{ String(index + 1).padStart(2, '0') }}</span><Link :href="route('guides.user-preview', guide.uuid)">{{ guide.title }}</Link><button type="button" :aria-label="`Lepas ${guide.title}`" @click="removing = { type: 'guide', item: guide }">×</button></li></ol><p v-else class="empty">Belum ada materi terlampir.</p><button type="button" class="outline" @click="showGuidePicker = !showGuidePicker">+ Attach guide</button><form v-if="showGuidePicker" class="picker" @submit.prevent="attachGuides"><label v-for="guide in availableUnlinkedGuides" :key="guide.id"><input v-model="guideForm.guide_ids" type="checkbox" :value="guide.id" />{{ guide.title }}</label><p v-if="!availableUnlinkedGuides.length" class="empty">Tidak ada materi lain yang tersedia.</p><small v-if="guideForm.errors.guide_ids" class="error">{{ guideForm.errors.guide_ids }}</small><button type="submit" :disabled="!guideForm.guide_ids.length || guideForm.processing">Hubungkan materi</button></form></section>
                    <section class="panel attachment"><h2>Quest terlampir</h2><ol v-if="quests.length"><li v-for="(quest,index) in quests" :key="quest.id"><span class="order">{{ String(index + 1).padStart(2, '0') }}</span><span>{{ quest.title }}</span><button type="button" :aria-label="`Lepas ${quest.title}`" @click="removing = { type: 'quest', item: quest }">×</button></li></ol><p v-else class="empty">Belum ada quest terlampir.</p><button type="button" class="outline" @click="showQuestPicker = !showQuestPicker">+ Attach quest</button><form v-if="showQuestPicker" class="picker" @submit.prevent="attachQuests"><label v-for="quest in availableUnlinkedQuests" :key="quest.id"><input v-model="questForm.quest_ids" type="checkbox" :value="quest.id" />{{ quest.title }}</label><p v-if="!availableUnlinkedQuests.length" class="empty">Tidak ada quest lain yang tersedia.</p><small v-if="questForm.errors.quest_ids" class="error">{{ questForm.errors.quest_ids }}</small><button type="submit" :disabled="!questForm.quest_ids.length || questForm.processing">Hubungkan quest</button></form></section></aside></div>
        </div>
        <div v-if="removing" class="overlay" @click.self="removing = null"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="detach-title"><h2 id="detach-title">Lepas {{ removing.type === 'guide' ? 'materi' : 'quest' }}?</h2><p>{{ removing.item.title }} akan dilepas dari event ini.</p><div><button type="button" class="secondary" @click="removing = null">Batal</button><button type="button" class="danger" @click="detach">Lepas</button></div></section></div>
    </main></div>
</template>

<style scoped>
.event-detail-app{display:flex;min-height:100vh;background:#f5f7f8;color:#19333d;font-family:Inter,ui-sans-serif,system-ui,sans-serif}.event-detail-app main{flex:1;min-width:0}.topbar{height:64px;background:#fff;border-bottom:1px solid #dce6e8;padding:0 28px;display:flex;align-items:center;justify-content:space-between;color:#70858c;font-size:11px}.topbar strong,.topbar small{display:block}.topbar strong{color:#19333d;font-size:12px}.topbar small{font-size:10px}.content{max-width:1440px;margin:auto;padding:34px 26px 70px}.heading{margin-bottom:28px}.back{color:#007f78;font-size:12px;font-weight:700}.heading>div{display:flex;align-items:center;justify-content:space-between;gap:15px}.heading h1{font-size:30px;font-weight:750;letter-spacing:-.025em;margin:8px 0}.heading p,.schedule{font-size:13px;color:#70858c;margin:0}.edit{color:#007f78;font-size:12px;font-weight:700}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:28px}.metric{min-height:130px;background:#fff;border:1px solid #dce6e8;border-radius:12px;padding:20px;display:flex;flex-direction:column;align-items:start}.metric span{font-size:13px;color:#70858c}.metric strong{font-size:23px;font-weight:750;margin:18px 0 10px;overflow-wrap:anywhere}.metric i{width:32px;height:3px;border-radius:2px;background:#008b83;margin-top:auto}.columns{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(260px,1fr);gap:20px;align-items:start}.panel{background:#fff;border:1px solid #dce6e8;border-radius:12px;padding:24px;min-width:0}.panel h2{font-size:18px;font-weight:750;margin:0 0 8px}.main-panel .schedule{margin-bottom:20px}.image-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}.image-grid img{width:100%;height:220px;object-fit:cover;border-radius:9px}.visual-placeholder{min-height:220px;border-radius:10px;background:#16383d;color:#fff;padding:30px;display:flex;flex-direction:column;justify-content:center;overflow-wrap:anywhere}.visual-placeholder strong{font-size:26px}.visual-placeholder span{color:#9edfd5;font-size:14px;margin-top:10px}.description{color:#70858c;font-size:14px;line-height:1.7;white-space:pre-wrap;margin:24px 0 30px}.primary{display:inline-block;background:#007f78;color:#fff;border-radius:7px;padding:12px 20px;font-weight:700;font-size:12px;text-decoration:none}.attachment{margin-bottom:20px}.attachment ol{list-style:none;padding:0;margin:22px 0}.attachment li{display:flex;align-items:center;gap:12px;padding:9px 0;font-size:13px}.attachment li a{color:#19333d;text-decoration:underline;text-decoration-color:#9ccbc6;text-underline-offset:3px}.attachment li>span:nth-child(2){flex:1}.attachment .order{font-weight:700;color:#007f78}.attachment li button{margin-left:auto;border:0;background:none;color:#b74336;font-size:20px;cursor:pointer}.outline{border:1px solid #dce6e8;border-radius:7px;background:#fff;color:#007f78;padding:10px 14px;font-weight:700;cursor:pointer}.empty{font-size:12px;color:#70858c;margin:18px 0}.picker{display:grid;gap:10px;border-top:1px solid #e5edef;margin-top:16px;padding-top:16px;max-height:300px;overflow:auto}.picker label{display:flex;align-items:center;gap:8px;font-size:12px}.picker button{border:0;border-radius:7px;background:#007f78;color:#fff;padding:10px;font-weight:700;cursor:pointer}.picker button:disabled{opacity:.5}.error{color:#b74336}.overlay{position:fixed;inset:0;background:#122b32aa;display:grid;place-items:center;padding:16px;z-index:50}.dialog{background:#fff;border-radius:12px;padding:24px;width:min(100%,430px)}.dialog p{color:#70858c}.dialog>div{display:flex;justify-content:flex-end;gap:10px}.secondary,.danger{border-radius:7px;padding:10px 14px;font-weight:700;cursor:pointer}.secondary{border:1px solid #dce6e8;background:#fff;color:#007f78}.danger{border:0;background:#b74336;color:#fff}.event-detail-app :is(a,button,input):focus-visible{outline:2px solid #008b83;outline-offset:2px}@media(max-width:1050px){.columns{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:800px){.event-detail-app{display:block}}@media(max-width:600px){.content{padding:22px 14px}.heading h1{font-size:25px}.panel{padding:18px}.metrics{gap:10px}.metric{padding:16px;min-height:110px}.metric strong{font-size:19px}}
</style>
<style scoped>
.heading-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.heading-actions a{border:1px solid #dce6e8;border-radius:7px;padding:9px 12px;text-decoration:none;font-size:12px;font-weight:700;color:#007f78}.heading-actions .preview{background:#e5f5f1;border-color:#c8e6df}
</style>
